import{_ as r}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a}from"./chunks/BDM.scaBLLhv.js";import{_ as t,o as n,c as o,a3 as s}from"./chunks/framework.g9mfNVRQ.js";const v=JSON.parse('{"title":"Arrêter le capteur","description":"","frontmatter":{"source_hash":"2b688cafdf","source_commit":"ea9ce3a"},"headers":[],"relativePath":"fr/use/stopsensor.md","filePath":"fr/use/stopsensor.md"}'),i={name:"fr/use/stopsensor.md"};function p(l,e,u,c,d,m){return n(),o("div",null,[...e[0]||(e[0]=[s('<p>Arrêter un capteur dans xDrip a des fonctions très différentes selon le capteur.</p><h3 id="g6-and-1" tabindex="-1">G6 et 1 <a class="header-anchor" href="#g6-and-1" aria-label="Permalink to &quot;G6 et 1 {#g6-and-1}&quot;">​</a></h3><p>La documentation de référence se trouve <a href="https://navid200.github.io/xDrip/docs/Proper-connectivity.html" target="_blank" rel="noreferrer">ici</a>.</p><h3 id="g7-and-1" tabindex="-1">G7 et 1+ <a class="header-anchor" href="#g7-and-1" aria-label="Permalink to &quot;G7 et 1+ {#g7-and-1}&quot;">​</a></h3><p>Ces capteurs s&#39;arrêtent d&#39;eux-mêmes au bout de 10 jours et 12 heures. Certains émetteurs dotés d&#39;un firmware différent annoncent à la place une durée de vie plus longue de 15 jours et 12 heures ; xDrip le détecte automatiquement à partir du firmware de l&#39;émetteur, ce n&#39;est pas un paramètre à choisir.</p><br><h3 id="libre" tabindex="-1">Libre <a class="header-anchor" href="#libre" aria-label="Permalink to &quot;Libre {#libre}&quot;">​</a></h3><p>xDrip ne peut pas arrêter un capteur Libre ; en fait, ce capteur ne peut pas être arrêté : s&#39;il ne tombe pas en panne, il fonctionne pendant toute sa durée de vie et s&#39;arrête de lui-même au bout de 14 jours et 12 heures.</p><p>L&#39;arrêt du capteur dans xDrip sert uniquement à invalider les étalonnages précédents. Cette opération est nécessaire et recommandée à chaque remplacement du capteur.</p><br><div class="admonition xdrip"><p class="admonition-title"><img src="'+r+'" style="zoom:75%;"></p><p> Arrêter le capteur</p></div><p>Confirmez avec ARRÊTER LE CAPTEUR, sauf si vous voulez seulement <a href="./../calibrate/calibrate.html#reset-all-calibrations">réinitialiser tous les étalonnages</a>.</p><div class="admonition xdripitem"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"> Arrêt du capteur <span class="symbol"></span></p><p> N&#39;arrêtez votre capteur que lorsque vous planifiez de l&#39;enlever, sinon laissez fonctionner!</p><p>       <span style="background-color:white;color:black;"> ARRÊTER LE CAPTEUR </span></p></div><p>Confirmez que vous voulez arrêter le capteur.</p><div class="admonition xdripitem"><p class="admonition-title">Êtes-vous sûr?</p><p> Voulez-vous arrêter le capteur?</p><p>       NON    <span style="background-color:white;color:black;"> OUI </span></p></div><p>Si vous changez d&#39;avis et que le capteur n&#39;a pas encore expiré, vous pouvez toujours le <a href="./startsensor.html#libre">« redémarrer »</a> : la session en cours reprendra et un nouvel étalonnage pourra être demandé. xDrip ne redémarre pas physiquement les capteurs Libre.</p><br><h3 id="followers-and-companion-apps" tabindex="-1">Abonnés et applications compagnon <a class="header-anchor" href="#followers-and-companion-apps" aria-label="Permalink to &quot;Abonnés et applications compagnon {#followers-and-companion-apps}&quot;">​</a></h3><p>Arrêter un capteur n&#39;a aucun intérêt avec une application abonnée.</p><div class="warning custom-block"><p class="custom-block-title">Attention</p><p>La seule exception est <a href="./sync.html#accept-followers-actions">l&#39;abonné xDrip Sync, qui peut transmettre la commande de démarrage ou d&#39;arrêt au capteur s&#39;il est directement connecté au xDrip principal</a>.<br> N&#39;utilisez pas Démarrer et Arrêter le capteur avec un abonné xDrip Sync, à moins d&#39;être sûr que la personne qui a le téléphone xDrip principal saura quoi faire d&#39;un capteur arrêté !</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.03" target="_blank" rel="noreferrer"><em>Dernière modification le 6/7/2026</em></a></p>',22)])])}const _=t(i,[["render",p]]);export{v as __pageData,_ as default};
